def minimumOneBitOperations(n: int) -> int:
    # Recursively compute minimum one bit ops
    if n == 0:
        return 0
    # Find most significant bit position k
    k = n.bit_length() - 1
    # Use the recurrence: ops(n) = 2^k - ops(n ^ 2^k)
    return (1 << k) - minimumOneBitOperations(n ^ (1 << k))
